'use client';
import {FormEvent,useState} from 'react';
import {useRouter} from 'next/navigation';
import {adminApi,session,TokenResponse} from '../../lib/api';
export default function Login(){const router=useRouter();const[email,setEmail]=useState('');const[password,setPassword]=useState('');const[challenge,setChallenge]=useState<string|null>(null);const[code,setCode]=useState('');const[error,setError]=useState('');const[busy,setBusy]=useState(false);
async function accept(t:TokenResponse){session.set(t);try{await adminApi.summary(t.accessToken);router.replace('/')}catch{session.clear();throw new Error('This account is not authorised to access OakPay Admin.')}}
async function submit(e:FormEvent){e.preventDefault();setError('');setBusy(true);try{if(challenge){await accept(await adminApi.verify2fa(challenge,code));return}const t=await adminApi.login(email.trim().toLowerCase(),password);if(t.requiresTwoFactor&&t.challengeToken){setChallenge(t.challengeToken);return}await accept(t)}catch(e){setError(e instanceof Error?e.message:'Sign in failed')}finally{setBusy(false)}}
return <main className="login-page"><div className="login-card"><div className="brand login-brand">Oak<span>Pay</span></div><div className="eyebrow">Operations portal</div><h1>{challenge?'Verify administrator':'Admin sign in'}</h1><p>{challenge?'Enter the 6-digit code from your authenticator app.':'Secure access for authorised OakPay operations staff.'}</p><form onSubmit={submit}>{!challenge?<><label>Email</label><input value={email} onChange={e=>setEmail(e.target.value)} type="email" required/><label>Password</label><input value={password} onChange={e=>setPassword(e.target.value)} type="password" required/></>:<><label>Authenticator code</label><input value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,'').slice(0,6))} inputMode="numeric" maxLength={6} required/></>}{error?<div className="form-error">{error}</div>:null}<button className="primary-action" disabled={busy}>{busy?'Please wait…':challenge?'Verify & continue':'Sign in'}</button></form></div></main>}
